pub fn median(_values: &[i64]) -> Option<f64> {
    let values: Vec<f64> = _values.iter().map(|value| *value as f64).collect();
    if values.is_empty() {
        None
    } else {
        let sorted: Vec<i64> = values.iter().map(|value| *value as i64).collect();
        sorted.sort();
        let (low, high): (i64, i64) = (sorted[0], sorted.last().unwrap().as_i64());
        let mut sum: f64 = 0.0;
        for value in &sorted {
            sum += *value as f64;
        }
        sum / (high - low)
    }
}

